  <script>
const players = new Map(); // key: containerId -> WaveSurfer instance

function createWaveSurfer(url, containerId, dotNetRef, waveColor, progressColor) {
    // bereits vorhanden? dann erst zerstören (Hot-Reload / Re-Init)
    destroy(containerId);

    const wavesurfer = WaveSurfer.create({
        height: 44,
        container: '#' + containerId,
        url: url,
        waveColor: waveColor || '#E74C3C',
        progressColor: progressColor || '#ef6f61',
        cursorColor: '#919191',
        barWidth: 2,
        barGap: 3,
        barRadius: 2,
        mediaControls: false
    });

    players.set(containerId, {ws: wavesurfer, dotNetRef});

    wavesurfer.on('play', () => dotNetRef?.invokeMethodAsync('HandlePlay'));
    wavesurfer.on('pause', () => dotNetRef?.invokeMethodAsync('HandlePause'));
    wavesurfer.on('finish', () => dotNetRef?.invokeMethodAsync('HandleFinish'));
}

function play(containerId) {
    const p = players.get(containerId);
    p?.ws?.play();
}

function pause(containerId) {
    const p = players.get(containerId);
    p?.ws?.pause();
}

function stop(containerId) {
    const p = players.get(containerId);
    if (!p?.ws) return;
    try {
        p.ws.stop();
    } catch {
    }
    // Stop hält an den Anfang; bei Bedarf zusätzlich p.ws.seekTo(0)
}

function load(containerId, url) {
    const p = players.get(containerId);
    p?.ws?.load(url);
}

function destroy(containerId) {
    const p = players.get(containerId);
    if (!p) return;
    try {
        p.ws?.unAll?.();  // alle Handler entfernen (falls verfügbar)
        p.ws?.destroy?.();
    } catch {
    }
    players.delete(containerId);
}
</script>

