					hideDiv('loginPAGE');
					showDiv('mantenimientoPAGE');


					isLoginVisible=false;
					isMantenimientoVisible=true;
				}
				//calculo del tiempo estimado de espera
				var tiempo = "AGOTADO.";
				var ini = new MyDate(results[0].fechaInicio);
				//var now = new Date();
				var now = new MyDate(results[0].hoy);
				ini = ini.date.getTime();
				now = now.date.getTime();
				if (now > ini){
					var time = now - ini;
					time = time/(1000*60);
					if (time < parseInt(results[0].tiempoEstimado)){
						time = parseInt(results[0].tiempoEstimado) - time;
						tiempo = parseInt(time) + " minutos.";
					}
				}
