function isIE() 
{ 
	var browserMsg = navigator.userAgent.toLowerCase(); 
	//      alert(browserMsg); 
	if (navigator.appName == "Microsoft Internet Explorer")
			return true; 

	return false; 
} 

function isEdge()

{
       var agt = navigator.userAgent;
