<body>

    <!-- Background Sparks -->
    <canvas id="sparkCanvas"></canvas>

    <div class="content-wrapper">
        <!-- Headline -->
        <div class="headline">ZONE 01</div>

        <!-- 3D Rotating Text -->
        <div class="scene">
            <div class="word-wrapper">
                <div class="char" data-char="東"><span>東</span></div>
                <div class="char" data-char="京"><span>京</span></div>
            </div>
        </div>

        <!-- Footer -->
        <div class="system-status" id="statusText">System Ready // Connected</div>
    </div>

    <script>
        // --- Spark Logic ---
        const canvas = document.getElementById('sparkCanvas');
        const ctx = canvas.getContext('2d');

        let width, height;
        let sparks = [];

        function resize() {
            width = canvas.width = window.innerWidth;
            height = canvas.height = window.innerHeight;
        }
        window.addEventListener('resize', resize);
        resize();

        class Spark {
            constructor() {
                // Start from bottom randomly
                this.x = Math.random() * width;
                this.y = height + 50;

                // Shoot upwards with slight curve
                this.vx = (Math.random() - 0.5) * 4; // Horizontal drift
                this.vy = -Math.random() * 8 - 6;   // Vertical speed (Fast)

                this.life = 100;
                this.decay = Math.random() * 2 + 1;
                this.size = Math.random() * 2 + 1;
                this.length = Math.random() * 80 + 40; // "Extended" length
                this.color = Math.random() > 0.8 ? '#ffffff' : '#ffff00'; // Mostly yellow, some white
            }

            update() {
                this.x += this.vx;
                this.y += this.vy;
                this.life -= this.decay;
                this.length -= 1; // Shrink tail as it goes up
            }

            draw() {
                if (this.life <= 0) return;

                ctx.save();
                ctx.globalAlpha = this.life / 100;
                ctx.strokeStyle = this.color;
                ctx.lineWidth = this.size;
                ctx.lineCap = 'round';

                // Draw a long streak (the "Extended" effect)
                // Start from current pos, draw back towards where it came from
                const startX = this.x;
                const startY = this.y;
                const endX = this.x - (this.vx * (this.length / 5));
                const endY = this.y - (this.vy * (this.length / 5));

                ctx.beginPath();
                ctx.moveTo(endX, endY);
                ctx.lineTo(startX, startY);
                ctx.stroke();

                // Add a small glowing head
                ctx.fillStyle = '#fff';
                ctx.beginPath();
                ctx.arc(startX, startY, this.size * 2, 0, Math.PI * 2);
                ctx.fill();

                ctx.restore();
            }
        }

        function animateSparks() {
            ctx.clearRect(0, 0, width, height);

            // Spawn sparks
            if (sparks.length < 100) {
                if (Math.random() > 0.6) {
                    sparks.push(new Spark());
                }
                // Burst occasionally
                if (Math.random() > 0.95) {
                    for(let i=0; i<5; i++) sparks.push(new Spark());
                }
            }

            for (let i = 0; i < sparks.length; i++) {
                sparks[i].update();
                sparks[i].draw();

                if (sparks[i].life <= 0 || sparks[i].y < -50) {
                    sparks.splice(i, 1);
                    i--;
                }
            }

            requestAnimationFrame(animateSparks);
        }

        animateSparks();

        // --- Subtle 3D Tilt Interaction ---
        const wrapper = document.querySelector('.word-wrapper');
        document.addEventListener('mousemove', (e) => {
            const x = (window.innerWidth / 2 - e.clientX) / 50;
            const y = (window.innerHeight / 2 - e.clientY) / 50;

            // Keep the base X rotation (10deg) but add mouse interaction
            wrapper.style.transform = `rotateY(${x}deg) rotateX(${10 + y}deg)`;
        });

        // Hover effect for status text
        const status = document.getElementById('statusText');
        status.addEventListener('mouseenter', () => {
            status.innerText = "ACCESS GRANTED";
        });
        status.addEventListener('mouseleave', () => {
            status.innerText = "System Ready // Connected";
        });
    </script>
</body>
