function loginFormIntercept(form){
      $(form).submit(function(e){
        e.preventDefault();

        var form = this;
        var values = {};
        $.each($(form).serializeArray(), function(i, elem){
            values[elem.name] = elem.value;
        })

        $.ajax({
          url: '/user/login/', //form.attr('action'),
          method: 'POST',
          data: JSON.stringify(values),
        })
        .done(function(data){
